import{_ as t,o as e,c as a,a3 as r}from"./chunks/framework.BwzYn71E.js";const b=JSON.parse('{"title":"流量物流蓝图库","description":"","frontmatter":{"translationSource":{"title":"流量物流蓝图库","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=iGsD2TAazUlL90onJtfkps","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/flow-rate-logistics-blueprint-library"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/flow-rate-logistics-blueprint-library"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/flow-rate-logistics-blueprint-library"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/flow-rate-logistics-blueprint-library"}]]},"headers":[],"relativePath":"zh/flow-rate-logistics-blueprint-library.md","filePath":"zh/page-iGsD2TAazUlL90onJtfkps.md"}'),s={name:"zh/flow-rate-logistics-blueprint-library.md"};function l(i,p,o,n,d,c){return e(),a("div",null,[...p[0]||(p[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="流量物流蓝图库" aria-hidden="true"></span><h1 id="流量物流蓝图库" tabindex="-1">流量物流蓝图库 <a class="header-anchor" href="#流量物流蓝图库" aria-label="Permalink to &quot;流量物流蓝图库&quot;">​</a></h1><blockquote><p>源页面 ID：<code>iGsD2TAazUlL90onJtfkps</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=iGsD2TAazUlL90onJtfkps" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><details><summary>先做常用分数</summary><p>分母 2 3 4 5 6 8 9 10 12这些</p><p>太简单的就不用管了，2,3,6啥的</p><p>做一下也无所谓吧，可能真有人需要1/6</p><p>那可以直接穷举</p></details><details><summary>考虑基于迟滞的吗</summary><p>不考虑吧，倒是搜出来的结构要验证一下会不会被bug影响</p><p>基于迟滞有什么说法吗</p><p>有的会面积很优</p><p>传送带\\管道同结构效果不同，只能构造某些特定分母，是bug，有被利用的可能，但是预料外的会很恶心</p><p>我是觉得只要能用，就没什么不能收录的</p><p>草草草草 恍然大悟 不对 恍然大迷</p></details><details><summary>筛选标准</summary><p>我觉得可以加点筛选<br> 管道和传送带也需要分开</p><p>Zirunwang: 10-12 02:27:29<br> 所属蓝图组<br> 名称<br> 蓝图码<br> 所在账号（隐藏）<br> 简介<br> tags<br> 图片<br> 备注</p><p>限流结构的转置有必要放上去吗</p><p>没必要吧，反正结果一样（</p><p>正常来讲是这样，但是暖机时长和受物流bug的影响效果不一样</p><p>帕累托前沿</p><p>如果一个结构本身没有哪方面很优，但是作为子结构能构造出更优的大结构，它有必要单独列出来吗</p><p>它能用于构造更优大结构就是优势</p><p>作为子结构需要考虑接口数量，但空闲接口越多意味着利用率越低</p><p>我感觉 end to end 吧，让用户可以不动脑比较好</p></details><details><summary>要不要为蓝图制定一种数据格式-封闭</summary><p>难道说，用编码而不是png？</p><p>是，我想这样。无损蓝图，而且实际体积还会小。</p><p>那还真能借隔壁（IndustrialPlanner）的，甚至在那边生成完了，导出为一图流所用的格式</p><p>仿真器把渲染的核心代码给我了，一图流打算就用这个绘图，以后应该可以无缝衔接</p><p>意思就是我不用再让ai分析整个仿真器的仓库去找这玩意，然后再去模仿，而且后续相关功能如果有更新他会提醒我</p><p>而且仿真器的作者已经准备开发给第三方内嵌的渲染模块了，顺利的话一图流甚至直接调用就行</p><p>如果模拟器作者愿意开放导入json就更好了</p><p>是不是已经有了</p><p>有的，数据格式自己去看</p><p>或者搓几个简单的小玩意导出一下看看</p></details><details><summary>给出输出序列吗，暖机时长是否必要-封闭</summary><p>我感觉输出序列还是要给的，包括从空和从满</p><p>输出序列可以得到暖机时长和均匀性？</p><p>主要是为了均匀性吧</p><p>不一定能给出输出序列吧，同一结构的不同初始条件结果不一定一样</p><p>总不能枚举每个分流器汇流器的初始状态来吧</p><p>我去还真是</p></details><p>其实应该先从小分数开始做</p><p>然后这些问题就会自动消失</p><p><strong>当前需求</strong></p><p>x/6,x/7, x/11, x/30(排除x/5,x/6), 1/x限速器</p><p>1:4分流，1:6分流，1:1:3分流</p><p>325/799限速器</p><p><a href="/endfield-skydoc/logistics/src/assets/attachments/result.txt-f1b983b7327ad752.txt">附件：result.txt</a></p><blockquote><p>原件：result.txt；大小：7324；objKey：<code>d6d70bfc7f7949e3a6eca412fc7f542b</code>；本地状态：已下载。</p></blockquote></div>',1)])])}const f=t(s,[["render",l]]);export{b as __pageData,f as default};
